import hashlib,json,os,sqlite3,stat,subprocess,sys,urllib.error,urllib.parse,urllib.request
from pathlib import Path
OWNED=Path('/tmp/qa-resume-20261008-child-ciivjupc')
CONFIG=OWNED/'child.yaml'
NODE='15961ef7-81b4-43f3-80c8-1b6977ca2aea'
AGENT='agent-ab15a133-73cd-4025-8c97-f2ff37e000f5'
CHILD=(49873,137980573,65534,'d55dc5cd9b1a697a76f0bf6dccb3347b7715ef760173d31d1d1e57db96373add')
MANIFEST='c8142503fc467066265b67a1db641ec3274119961f65cdadcd92f2ba26a2e2ce'
DB=(33,155,65534,65534,0o644)
PARENT_MAIN=32487
CONFIG_SHA='2d36aeb7f541573683c5458f35e8322ea7b84024f33d01541f720b144dbbab1c'
PARENT_UNIT='nodesteer-agent-repair-20260930-101945-native-4.service'
HUB='http://192.168.100.209:18080'
TRANSFER='256de7fe-c8df-4825-a7cb-651568b4ff34'
TIMEOUT=12
def blocked(reason):
 print(json.dumps({'status':'BLOCKED','reason':reason},separators=(',',':')));raise SystemExit(0)
def sha(path):
 h=hashlib.sha256()
 with Path(path).open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
def proc(pid):
 p=Path('/proc')/str(pid);raw=(p/'stat').read_text();tail=raw[raw.rfind(')')+2:].split()
 uid=int(next(x for x in (p/'status').read_text().splitlines() if x.startswith('Uid:')).split()[1])
 argv=[x.decode(errors='replace') for x in (p/'cmdline').read_bytes().split(b'\0') if x]
 return int(tail[19]),uid,argv
class NoRedirect(urllib.request.HTTPRedirectHandler):
 def redirect_request(self,req,fp,code,msg,headers,newurl):return None

def owner_credential():
 st=OWNED.lstat()
 if OWNED.is_symlink() or (st.st_dev,st.st_ino,st.st_uid,stat.S_IMODE(st.st_mode))!=(33,135,65534,0o700):raise ValueError('owned_root_guard')
 u=subprocess.run(['systemctl','show',PARENT_UNIT,'-p','LoadState','-p','ActiveState','-p','MainPID'],capture_output=True,text=True,timeout=6)
 props=dict(x.split('=',1) for x in u.stdout.splitlines() if '=' in x)
 if u.returncode or props!={'LoadState':'loaded','ActiveState':'active','MainPID':str(PARENT_MAIN)}:raise ValueError('parent_unit_guard')
 mp=OWNED/'owner-manifest.json';ms=mp.lstat()
 if mp.is_symlink() or not stat.S_ISREG(ms.st_mode) or (ms.st_uid,stat.S_IMODE(ms.st_mode))!=(65534,0o600) or sha(mp)!=MANIFEST:raise ValueError('manifest_guard')
 m=json.loads(mp.read_text())
 if (m.get('node_id'),m.get('agent_id'),m.get('directory'),m.get('directory_dev'),m.get('directory_ino'),m.get('directory_uid'))!=(NODE,AGENT,str(OWNED),33,135,65534):raise ValueError('manifest_identity')
 marker=OWNED/'owner.marker';mt=marker.lstat()
 if marker.is_symlink() or not stat.S_ISREG(mt.st_mode) or (mt.st_uid,mt.st_gid,stat.S_IMODE(mt.st_mode))!=(65534,65534,0o600) or marker.read_text(encoding='utf-8')!=m.get('owner_marker'):raise ValueError('owner_marker_guard')
 child=m.get('child',{})
 if (child.get('pid'),child.get('starttime'),child.get('uid'),child.get('exe_sha256'))!=CHILD:raise ValueError('manifest_child')
 ticks,uid,argv=proc(CHILD[0])
 if (ticks,uid)!=(CHILD[1],CHILD[2]) or str(CONFIG) not in argv or sha(Path('/proc',str(CHILD[0]),'exe'))!=CHILD[3]:raise ValueError('child_process_guard')
 cfg=m.get('config',{})
 if Path(cfg.get('path',''))!=CONFIG:raise ValueError('config_path_guard')
 cs=CONFIG.lstat()
 if CONFIG.is_symlink() or not stat.S_ISREG(cs.st_mode) or (cs.st_uid,stat.S_IMODE(cs.st_mode))!=(65534,0o600) or sha(CONFIG)!=CONFIG_SHA:raise ValueError('config_stat_or_sha_guard')
 cfg_agent=[]
 with CONFIG.open('r',encoding='utf-8') as f:
  for line in f:
   if line.startswith('agent_id: '):cfg_agent.append(json.loads(line.split(': ',1)[1].strip()))
 if cfg_agent!=[AGENT]:raise ValueError('config_agent_guard')
 dbp=OWNED/'data'/'state.db';ds=dbp.lstat()
 if dbp.is_symlink() or not stat.S_ISREG(ds.st_mode) or (ds.st_dev,ds.st_ino,ds.st_uid,ds.st_gid,stat.S_IMODE(ds.st_mode))!=DB:raise ValueError('database_stat_guard')
 uri='file:'+urllib.parse.quote(str(dbp),safe='/')+'?mode=ro';db=sqlite3.connect(uri,uri=True,timeout=2)
 try:
  db.execute('PRAGMA query_only=ON');tables={x[0] for x in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
  if 'identity' not in tables:raise ValueError('identity_table_missing')
  row=dict(db.execute('SELECT key,value FROM identity WHERE key IN (?,?)',('node_id','agent_id')))
  credrow=db.execute('SELECT value FROM identity WHERE key=?',('credential',)).fetchone()
 finally:db.close()
 if row!={'node_id':NODE,'agent_id':AGENT} or not credrow or not isinstance(credrow[0],str) or not credrow[0]:raise ValueError('database_identity_guard')
 return credrow[0]
def relay_get(token):
 url=HUB+'/agent/transfers/'+urllib.parse.quote(TRANSFER,safe='')+'/download'
 req=urllib.request.Request(url,headers={'X-NodeSteer-Agent-ID':AGENT,'X-NodeSteer-Agent-Token':token},method='GET')
 op=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect)
 try:r=op.open(req,timeout=TIMEOUT);status,headers,stream=r.status,r.headers,r
 except urllib.error.HTTPError as e:status,headers,stream=e.code,e.headers,e
 out={'http_status':status,'content_type':headers.get('Content-Type'),'content_length':headers.get('Content-Length'),'body_bytes_read':0,'json_error':False,'expected_target_denial':False}
 try:
  if status==403:
   raw=stream.read(4097);out['body_bytes_read']=len(raw)
   if len(raw)<=4096:
    try:
     d=json.loads(raw);out['json_error']=isinstance(d,dict) and isinstance(d.get('error'),str);out['expected_target_denial']=out['json_error'] and d.get('error')=='agent is not a transfer target'
    except Exception:pass
 finally:stream.close()
 return out
def main():
 try:
  token=owner_credential();response=relay_get(token);del token
 except Exception:blocked('owner_guard_or_relay_request_failed')
 ok=response.get('http_status')==403 and response.get('expected_target_denial') and response.get('json_error')
 print(json.dumps({'status':'PASS' if ok else 'PARTIAL','owner_guard_passed':True,'wrong_target_download':response,'credential_value_persisted_or_printed':False,'response_body_persisted_or_printed':False},separators=(',',':')))
if __name__=='__main__':main()

